(function(){'use strict';
const C=THJournalCore,F=THFinanceCore;
function deskJournalSummary(){const os=allOrders(),desk=os.filter(o=>o.deskManaged&&!o.excludeFromTotals),pending=desk.filter(o=>!['CLEAR','CANCELLED CLEAR'].includes(o.clear)&&o.deskStatus!=='VOIDED');return `<section class="paper section-gap"><div class="panel-heading"><div><h2>Seluruh order, satu catatan</h2><p class="muted">${desk.length} order meja laundry · ${pending.length} masih perlu penyelesaian. Barang yang sudah ditautkan ke pesanan tidak dihitung dua kali.</p></div>${btn('Lihat semua order','goto','laundry','btn','arrow')}</div><p>Order langsung terlihat sejak check-in. Barang selesai, pembayaran diterima, setoran cocok, dan pembukuan adalah status yang berbeda.</p><div class="order-list">${pending.slice(0,4).map(orderRow).join('')}</div>${['Owner','Finance'].includes(ui.role)?btn('Periksa pembukuan & laporan','nav','finance','text-btn','wallet'):''}</section>`;}
let range=null,kind='all',search='';
function initial(){const d=F.today('Asia/Jakarta');return {start:d+'T00:00',end:d+'T23:59'};}
function selected(){range=range||initial();return C.events({...db,orders:allOrders()},window.THCloud?.state?.finance).filter(e=>C.matches(e.at,range)&&(kind==='all'||e.kind===kind)&&`${e.label} ${e.source} ${e.division}`.toLowerCase().includes(search.toLowerCase()));}
function row(e){const precise=C.local(e.at);return `<tr><td class="journal-when"><span class="journal-time">${precise.slice(11)} <small>WIB</small></span><small>${dt(precise.slice(0,10))}</small></td><td class="journal-activity"><strong>${esc(e.label)}</strong>${e.actor?'<small class="journal-actor">'+esc(e.actor)+'</small>':''}${allOrders().some(o=>o.id===e.source)?btn('Buka order','order',e.source,'text-btn'):''}${allOrders().some(o=>o.id===e.source)?'<small>Order '+esc(e.source)+'</small>':''}</td><td class="journal-division">${badge(e.division,e.division.includes('Laundry')?'blue':'neutral')}</td><td class="number journal-amount">${e.amount===null?'—':money(e.amount)}</td></tr>`;}
renderHome=function(){range=range||initial();const all=C.events({...db,orders:allOrders()},window.THCloud?.state?.finance),inRange=all.filter(e=>C.matches(e.at,range)),rows=selected(),unknown=all.filter(e=>!e.precise).length;
const created=inRange.filter(e=>e.kind==='order'&&!e.excludeFromTotals),finished=inRange.filter(e=>e.kind==='completed'),posted=inRange.filter(e=>e.kind==='finance'),reports=inRange.filter(e=>e.kind==='report'),active=allOrders().filter(o=>!o.excludeFromTotals&&!['Selesai','Dibatalkan'].includes(o.stage));
return `<div class="page-heading"><div><span class="eyebrow">CATATAN KECIL, KENDALI BESAR · WIB</span><h1>Jurnal usaha<span class="heading-dot">.</span></h1><p>Telusuri order, transaksi, dan aktivitas tim berdasarkan waktu.</p></div>${ui.role==='Finance'?btn('Buka laporan','nav','finance','btn primary','wallet'):btn('Tambah order','new-order','','btn primary','plus')}</div>
<section class="journal-filters paper" aria-label="Filter waktu jurnal"><div class="panel-heading"><div><h2>Pilih rentang waktu</h2><p class="muted">Tanggal dan jam mengacu ke Asia/Jakarta (WIB).</p></div><div class="button-row">${['Hari ini','Kemarin','7 hari','Bulan ini'].map(x=>`<button class="btn small" data-journal-preset="${x}">${x}</button>`).join('')}</div></div>
<form data-journal-range class="journal-range-form"><label>Dari tanggal & jam<input name="start" type="datetime-local" value="${range.start}" required></label><label>Sampai tanggal & jam<input name="end" type="datetime-local" value="${range.end}" required></label><button class="btn primary" type="submit">Terapkan rentang</button><div class="form-error" role="alert"></div></form>
<div class="journal-range-caption">${icon('clock')} ${esc(range.start.replace('T',' · '))} → ${esc(range.end.replace('T',' · '))} WIB <span>Menit terakhir termasuk dalam hasil</span></div></section>
<div class="metric-grid">${metric('Order diterima',created.length,'penerimaan dalam rentang','laundry','blue')}${metric('Laundry selesai',finished.length,'penyelesaian dalam rentang','check','green')}${metric('Transaksi dibukukan',posted.length,'berdasarkan waktu pencatatan','wallet','yellow')}${metric('Laporan aktivitas',reports.length,'Global & Laundry terkirim','note','blue')}</div>
${!allOrders().length&&ui.role==='Owner'?`<section class="journal-start paper"><div><span class="eyebrow">BAB BARU TOP HILLS</span><h2>Mulai dari ruang yang rapi.</h2><p>Data usaha belum terisi. Akun tetap tersedia. Siapkan tim, paket layanan, dan saldo awal untuk memulai.</p>${btn('Periksa kesiapan usaha','readiness','','btn primary','arrow')}</div><img src="${basketSrc}" width="160" height="160" alt="Keranjang dengan pakaian terlipat"></section>`:''}
${deskJournalSummary()}<section class="paper"><div class="panel-heading"><div><h2>Linimasa aktivitas <span class="count">${rows.length}</span></h2><p class="muted">Urutan waktu terbaru. Nilai pada baris adalah nominal terkait, bukan total pendapatan.</p></div><button class="btn small" data-journal-export>${icon('download')} Unduh catatan</button></div>
<div class="journal-search"><label>Jenis aktivitas<select data-journal-kind>${[['all','Semua aktivitas'],['order','Order diterima'],['completed','Laundry selesai'],['activity','Tahapan laundry'],['finance','Transaksi dibukukan'],['report','Laporan Global / Laundry'],['closing','Pemeriksaan akhir kas'],['audit','Catatan perubahan']].map(([v,l])=>`<option value="${v}" ${kind===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Cari aktivitas<input type="search" data-journal-search value="${esc(search)}" placeholder="Order, nama, atau aktivitas"></label></div>
<div id="journal-events">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Waktu aktivitas</th><th>Kegiatan</th><th>Bagian usaha</th><th class="number">Nominal terkait</th></tr></thead><tbody>${rows.slice(0,200).map(row).join('')}</tbody></table></div>${rows.length>200?'<p class="muted">Menampilkan 200 aktivitas terbaru. Unduh catatan memuat seluruh hasil filter.</p>':''}`:empty('Belum ada aktivitas dalam rentang ini','Coba rentang lain atau mulai catat pekerjaan pertama.')}</div>
${unknown?`<p class="muted">${unknown} catatan lama belum memiliki jam yang pasti dan tidak dimasukkan dalam filter jam.</p>`:''}</section>
<div class="journal-footnote"><span>${active.length} order aktif saat ini · posisi terkini, di luar filter waktu</span>${ui.role==='Finance'?btn('Buka laporan','nav','finance','text-btn','arrow'):btn('Buka operasional','goto','laundry','text-btn','arrow')}</div>`;};
document.addEventListener('submit',e=>{const form=e.target.closest('[data-journal-range]');if(!form)return;e.preventDefault();const next=Object.fromEntries(new FormData(form));if(!C.valid(next)){form.querySelector('.form-error').textContent='Tanggal dan jam awal harus sebelum atau sama dengan akhir.';return;}range=next;render();});
document.addEventListener('change',e=>{if(e.target.matches('[data-journal-kind]')){kind=e.target.value;render();}if(e.target.matches('[data-journal-search]')){search=e.target.value;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-journal-preset]');if(b){const d=F.today('Asia/Jakarta'),p=b.dataset.journalPreset;range={start:(p==='Kemarin'?F.day(d,-1):p==='7 hari'?F.day(d,-6):p==='Bulan ini'?d.slice(0,7)+'-01':d)+'T00:00',end:(p==='Kemarin'?F.day(d,-1):d)+'T23:59'};render();}if(e.target.closest('[data-journal-export]')){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'"+'$&').replace(/"/g,'""')+'"';const lines=[['Waktu WIB','Aktivitas','Referensi','Alokasi','Nominal terkait'],...selected().map(x=>[C.local(x.at).replace('T',' '),x.label,allOrders().some(o=>o.id===x.source)?x.source:'',x.division,x.amount])];download('Top-Hills-Jurnal-'+range.start.slice(0,10)+'_'+range.end.slice(0,10)+'.csv','\uFEFF'+lines.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}});
window.THJournal={selected,getRange:()=>({...range||initial()})};
})();
